using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Collections.Generic;
namespace kok {
 internal static class ModuleDefinitions {
  internal static ActionSpec Action(string name,Need requires,bool writes,Func<ModuleContext,Dictionary<string,object>,Task<object>> execute,Dictionary<string,object> schema=null){return new ActionSpec{Name=name,Requires=requires,Writes=writes,Kind=writes?"write":"read",Schema=schema??ActionSchemas.For(name),Execute=execute};}
  internal static ActionSpec Command(string name,string title,string key,Need needs=Need.None){var a=Action(name,needs,false,(c,args)=>Task.FromResult((object)true),CapabilitySchema.Obj());a.Title=title;a.Kind="open";a.UiCommand=key;a.Surfaces=new[]{"palette"};if(name=="commandDocument")a.CapabilityId="documents.createDocument";if(name=="commandPresentation")a.CapabilityId="presentations.newPresentation";return a;}
  internal static ModuleRegistry Create(){
   var r=new ModuleRegistry();
   r.Register(new KokModule{Name="core",Required=true,Ui=true,Actions=new[]{Action("moduleCatalog",Need.None,false,(c,a)=>Task.FromResult(r.Catalog(c)),CapabilitySchema.Obj()),Action("setModuleEnabled",Need.NormalLibrary,true,(c,a)=>{string id=ModuleContext.Text(a,"id");bool on=Convert.ToBoolean(a["enabled"]);if(!on)c.StopModule(id);c.Library.SetModuleEnabled(id,on);c.Notify("modulesChanged",null);return Task.FromResult(r.Catalog(c));},CapabilitySchema.Obj(CapabilitySchema.Fields("id",CapabilitySchema.Str(64),"enabled",new Dictionary<string,object>{{"type","boolean"}}),new[]{"id","enabled"})),Command("commandLibrary","资料库","core.library"),Command("commandModules","模块管理","core.modules")},Facets=new[]{new FacetSpec{Name="core",Fields=new[]{"favorite","progress","position","chapter","opened","notes","width","height"}}}});
   var agentNames=AgentService.AgentTaskActions.Concat(AgentService.PlatformActions).Concat(new[]{"agentSessions","saveAgentSessions","agentPatch","agentCreatedStamp","agentUndoCreated"}).ToArray();
   var agentActions=agentNames.Select(name=>{
    bool stop=name=="agentTaskStop";bool run=new[]{"agentTaskStart","agentTaskResume","agentTaskDecide","agentTaskAdjust"}.Contains(name);bool writes=!new[]{"agentTaskList","agentTaskRead","agentTaskEvents","agentTaskTrace","agentSessions","agentCreatedStamp","agentHandoffPreview","agentHandoffRead","agentRuntimeInfo","agentMemoryList"}.Contains(name);
    var a=Action(name,stop?Need.None:Need.NormalLibrary|(run?Need.Ai|Need.Network:Need.None),writes,(c,args)=>(AgentService.AgentTaskActions.Contains(name)||AgentService.PlatformActions.Contains(name))?StopOrRun(c,name,args):AgentStorage(c,name,args));a.Emergency=stop;
    if(name!="agentTaskStart"&&name!="agentTaskList"&&name!="agentTaskStop"&&!name.StartsWith("agentHandoff")&&!new[]{"agentSessions","saveAgentSessions","agentPatch","agentCreatedStamp","agentUndoCreated"}.Contains(name))a.Schema=CapabilitySchema.Obj(CapabilitySchema.Fields("taskId",CapabilitySchema.Str(32)),new[]{"taskId"},true);return a;
   }).Select(a=>{a.Schema=ActionSchemas.For(a.Name);return a;}).Concat(new[]{Command("commandAgent","Agent","agent.open",Need.Ai|Need.NormalLibrary)}).ToArray();
   r.Register(new KokModule{Name="agent",Ui=true,Actions=agentActions,AgentTools=LibraryToolDefinitions.Tools().Concat(new[]{AgentCalculator.Tool()}).Concat(AgentCognition.Tools()).Concat(AgentAdvancedTools.Tools()).Concat(AgentVision.Tools()).Concat(AgentWeb.Tools()).Concat(AgentExecution.Tools()).ToArray(),Facets=new[]{new FacetSpec{Name="agent-tasks"}}});
   var docNames=new[]{"createDocument","documentSource","saveDocument","read"};var docActions=docNames.Select(n=>Action(n,new[]{"createDocument","saveDocument"}.Contains(n)?Need.NormalLibrary:Need.None,new[]{"createDocument","saveDocument"}.Contains(n),(c,a)=>NativeDocuments.Handle(c,n,a))).Concat(new[]{Command("commandDocument","新建文档","documents.new",Need.NormalLibrary)}).ToArray();
   r.Register(new KokModule{Name="documents",Kinds=new[]{"document","book"},Ui=true,Actions=docActions,AgentTools=DocumentToolDefinitions.Tools(),Facets=new[]{new FacetSpec{Name="documents"}}});
   var pptNames=new[]{"readPresentation","newPresentation","exportPresentation"};r.Register(new KokModule{Name="presentations",Kinds=new[]{"document"},Ui=true,Actions=pptNames.Select(n=>Action(n,n=="readPresentation"?Need.None:Need.NormalLibrary,n!="readPresentation",(c,a)=>NativeDocuments.Presentation(c,n,a))).Concat(new[]{Command("commandPresentation","新建演示文稿","presentations.new",Need.NormalLibrary)}).ToArray(),AgentTools=PresentationToolDefinitions.Tools(),Facets=new[]{new FacetSpec{Name="presentation-draft"}}});
   r.Register(WorkspaceModules.Operations());r.Register(WorkspaceModules.Jobs());r.Register(WorkspaceModule.Create());r.Register(McpModule.Create());
   foreach(var domain in DomainModules.Create())r.Register(domain);
   r.Register(new KokModule{Name="legacy",Required=true,Kinds=new string[0],Actions=MainWindow.LegacyNames().Except(DomainModules.Groups().Values.SelectMany(v=>v)).Except(docNames).Except(new[]{"bulkClassify","editOrganization"}).Select(name=>{var a=Action(name,LegacyRequirements.For(name),LegacyRequirements.Writes(name),(c,args)=>c.Legacy(name,args));a.Emergency=LegacyRequirements.Emergency(name);return a;}).ToArray(),Facets=new[]{new FacetSpec{Name="legacy-shell"}}});var toggle=r.Modules.Single(m=>m.Name=="core").Actions.Single(a=>a.Name=="setModuleEnabled");var toggleProperties=(Dictionary<string,object>)toggle.Schema["properties"];((Dictionary<string,object>)toggleProperties["id"])["enum"]=r.Modules.Where(m=>!m.Required).Select(m=>m.Name).ToArray();foreach(var action in r.Modules.SelectMany(m=>m.Actions)){string title;var titles=new Dictionary<string,string>{{"read","读取正文"},{"createDocument","新建文档"},{"bulkClassify","批量分类"},{"subtitles","读取字幕"},{"summarizeContent","总结内容"},{"presentationFromText","从文字制作演示"},{"workspaceSave","保存工作区对象"},{"indexLibrary","建立全文索引"}};if(titles.TryGetValue(action.Name,out title)){action.Title=title;if(action.UiCommand==null)action.Surfaces=action.Surfaces.Concat(new[]{"recipe"}).Distinct().ToArray();}}return r;
  }
  static Task<object> StopOrRun(ModuleContext c,string name,Dictionary<string,object> a){if(name=="agentTaskStop")return Task.FromResult((object)(c.Agent!=null&&c.Agent.RequestStop(ModuleContext.Text(a,"taskId"),a.ContainsKey("cancel")&&Convert.ToBoolean(a["cancel"]))));if(c.Agent==null)throw new InvalidOperationException("私密文件夹不启用 AI，请先返回普通资料库。");return c.Agent.HandleAgentTaskAction(name,a);}
  static Task<object> AgentStorage(ModuleContext c,string name,Dictionary<string,object> a){object result;if(name=="agentSessions")result=c.Library.ReadAgentSessions();else if(name=="saveAgentSessions"){c.Library.SaveAgentSessions(ModuleContext.Text(a,"text"));result=true;}else if(name=="agentPatch"){c.Library.ApplyAgentChanges(AgentTaskState.Get<List<AgentChange>>(a,"changes"));result=true;}else if(name=="agentCreatedStamp")result=c.Library.AgentCreatedStamp(ModuleContext.Text(a,"id"));else{c.Library.UndoAgentCreated(ModuleContext.Text(a,"id"),ModuleContext.Text(a,"stamp"));result=true;}return Task.FromResult(result);}
 }
 internal static class LegacyRequirements {
  static readonly string[] ai={"aiConfig","saveAiConfig","aiModels","translate","organizeFiles","chatWithFile","applyOrganization","runStudyTask","generateVideoOutline","knowledgeAiPreview","runKnowledgeAnalysis","runVisualEdit","lookupMusic","speechConfig","saveSpeechConfig","chooseSpeechFile","installSpeech","generateSubtitles"};
  static readonly string[] network={"aiModels","translate","organizeFiles","chatWithFile","runStudyTask","generateVideoOutline","knowledgeAiPreview","runKnowledgeAnalysis","runVisualEdit","lookupMusic","installSpeech","generateSubtitles","probeDownload","startDownloads","resumeDownload","installDownloadTools","loginDownloadSite","browserProbeDownload"};
  static readonly string[] normal={"downloadState","installDownloadTools","chooseDownloadFolder","chooseFfmpeg","probeDownload","startDownloads","pauseDownload","resumeDownload","cancelDownload","importDownload","revealDownload","clearDownloadHistory","loginDownloadSite","clearDownloadLogin","importDownloadLogin","browserProbeDownload","sources","addSource","changeSource","scanSources"};
  public static bool Emergency(string n){return n.StartsWith("cancel",StringComparison.Ordinal)||new[]{"diagnostics","vaultStatus","vaultActivity","lockPrivate","unlockPrivate"}.Contains(n);}
  public static Need For(string n){if(Emergency(n))return Need.None;Need need=Need.None;if(ai.Contains(n))need|=Need.Ai|Need.NormalLibrary;if(network.Contains(n))need|=Need.Network|Need.NormalLibrary;if(normal.Contains(n))need|=Need.NormalLibrary;return need;}
  public static bool Writes(string n){return !new[]{"diagnostics","library","formats","previewWindows","fileProperties","readHelp","appModeState","vaultStatus","vaultActivity","aiConfig","sources","subtitles","downloadState","speechConfig","creativeSource","creativeMediaState","fileChatHistory","musicOrganizationInput","knowledgeIndex","readTranslationView","translationDocument","probeCreativeMedia"}.Contains(n);}
 }
}
